using System;using System.Collections.Generic;using System.IO;using System.Linq;
namespace TrayLeaf {
 public sealed class AssociationRule {public AppRow Source{get;set;}public AppRow Target{get;set;}public bool Enabled{get;set;}}
 public sealed partial class Database {
  void Initialize100(){lock(gate){Execute("BEGIN IMMEDIATE");try{
   Execute("CREATE TABLE IF NOT EXISTS display_names(path TEXT PRIMARY KEY COLLATE NOCASE,name TEXT NOT NULL)");
   Execute("CREATE TABLE IF NOT EXISTS original_names(path TEXT PRIMARY KEY COLLATE NOCASE,name TEXT NOT NULL)");
   Execute("CREATE TABLE IF NOT EXISTS launch_rules(source TEXT PRIMARY KEY COLLATE NOCASE,source_name TEXT NOT NULL,target TEXT NOT NULL,target_name TEXT NOT NULL,args TEXT NOT NULL,admin TEXT NOT NULL,enabled TEXT NOT NULL)");
   Execute("CREATE TABLE IF NOT EXISTS profile_links(close_id INTEGER PRIMARY KEY REFERENCES saved_sets(id) ON DELETE CASCADE,restore_id INTEGER NOT NULL REFERENCES saved_sets(id) ON DELETE CASCADE,auto_sync TEXT NOT NULL DEFAULT '0')");
   if(!Query("PRAGMA table_info(profile_links)").Any(r=>r[1]=="auto_sync"))Execute("ALTER TABLE profile_links ADD COLUMN auto_sync TEXT NOT NULL DEFAULT '0'");Execute("PRAGMA user_version=4");Execute("COMMIT");}catch{Execute("ROLLBACK");throw;}}}
  public void SetAlias(string path,string name){if(String.IsNullOrWhiteSpace(path))throw new ArgumentException("此程序没有可用路径");name=(name??"").Trim();if(name.Length>80||name.IndexOfAny(new[]{'\r','\n','\0'})>=0)throw new ArgumentException("名称最多 80 个字符，不能包含换行");if(name.Length==0)Execute("DELETE FROM display_names WHERE path=?",path);else Execute("INSERT OR REPLACE INTO display_names(path,name) VALUES(?,?)",Path.GetFullPath(path),name);}
  public void RememberOriginalName(AppRow row){if(String.IsNullOrWhiteSpace(row.Path))return;Execute("INSERT OR IGNORE INTO original_names(path,name) VALUES(?,?)",row.Path,row.OriginalName??row.Name??Path.GetFileNameWithoutExtension(row.Path));}
  public string DisplayName(string path,string fallback){var rows=Query("SELECT name FROM display_names WHERE path=?",path??"");return rows.Count==0?fallback:rows[0][0];}
  public void ApplyName(AppRow row){if(row.OriginalName==null){var known=Query("SELECT name FROM original_names WHERE path=?",row.Path??"");row.OriginalName=known.Count>0?known[0][0]:row.Name;}row.Name=DisplayName(row.Path,row.OriginalName);}
  public List<AppRow> Aliases(){return Query("SELECT name,path FROM display_names").Select(x=>new AppRow{Name=x[0],Path=x[1],ProcessName=Path.GetFileName(x[1])}).ToList();}
  public bool HasActiveAssociations{get{return Query("SELECT source FROM launch_rules WHERE enabled='1' LIMIT 1").Count>0;}}
  public bool LinkedProfilesEnabled{get{return HasActiveAssociations||Get("linkProfiles","0")=="1";}}
  public List<AssociationRule> Associations(){return Query("SELECT source,source_name,target,target_name,args,admin,enabled FROM launch_rules").Select(x=>new AssociationRule{Source=new AppRow{Path=x[0],Name=DisplayName(x[0],x[1]),ProcessName=Path.GetFileName(x[0])},Target=new AppRow{Path=x[2],Name=DisplayName(x[2],x[3]),ProcessName=Path.GetFileName(x[2]),Args=x[4],Admin=x[5]=="1",ArgsKnown=true},Enabled=x[6]=="1"}).ToList();}
  public void SaveAssociation(AppRow source,AppRow target,bool enabled){if(String.IsNullOrWhiteSpace(source.Path)||String.IsNullOrWhiteSpace(target.Path)||!Path.IsPathRooted(source.Path)||!Path.IsPathRooted(target.Path))throw new ArgumentException("关联路径无效");if(target.Args.Length>30000||target.Args.IndexOf('\0')>=0)throw new ArgumentException("启动参数无效");lock(gate){Execute("BEGIN IMMEDIATE");try{Execute("INSERT OR REPLACE INTO launch_rules(source,source_name,target,target_name,args,admin,enabled) VALUES(?,?,?,?,?,?,?)",source.Path,source.OriginalName??source.Name,target.Path,target.OriginalName??target.Name,target.Args,target.Admin?"1":"0",enabled?"1":"0");if(enabled)Set("linkProfiles","1");ResyncLinksCore();Execute("COMMIT");}catch{Execute("ROLLBACK");throw;}}}
  public void SetAssociationEnabled(string path,bool enabled){lock(gate){Execute("BEGIN IMMEDIATE");try{Execute("UPDATE launch_rules SET enabled=? WHERE source=?",enabled?"1":"0",path);if(enabled)Set("linkProfiles","1");ResyncLinksCore();Execute("COMMIT");}catch{Execute("ROLLBACK");throw;}}}
  public void DeleteAssociation(string path){lock(gate){Execute("BEGIN IMMEDIATE");try{Execute("DELETE FROM launch_rules WHERE source=?",path);ResyncLinksCore();Execute("COMMIT");}catch{Execute("ROLLBACK");throw;}}}
  public AppRow RestoreTarget(AppRow source){var result=ProgramPresentation.Copy(source);var rule=Associations().FirstOrDefault(x=>x.Enabled&&String.Equals(x.Source.Path,source.Path,StringComparison.OrdinalIgnoreCase));if(rule!=null){result=ProgramPresentation.Copy(rule.Target);result.Selected=source.Selected;result.ArgsKnown=true;}ApplyName(result);return result;}
  public void MapClosedForRestore(IEnumerable<AppRow> rows){lock(gate){Execute("BEGIN IMMEDIATE");try{foreach(var source in rows.Where(x=>x.ItemStatus=="closed")){var row=RestoreTarget(source);Execute("UPDATE items SET name=?,path=?,args=?,admin=? WHERE id=?",row.Name,row.Path,row.Args,row.Admin?"1":"0",source.ItemId.ToString());}Execute("COMMIT");}catch{Execute("ROLLBACK");throw;}}}
  public long LinkedRestoreProfile(long close){var q=Query("SELECT restore_id FROM profile_links WHERE close_id=?",close.ToString());return q.Count==0?0:long.Parse(q[0][0]);}
  public void LinkProfiles(long close,long restore){if(!ListSets("profile_close").Any(x=>x.Id==close)||!ListSets("profile_restore").Any(x=>x.Id==restore))throw new ArgumentException("配置不存在");Execute("INSERT OR REPLACE INTO profile_links(close_id,restore_id,auto_sync) VALUES(?,?,'0')",close.ToString(),restore.ToString());}
  void SyncProfileCore(long close,string name,IEnumerable<AppRow> rows){if(!LinkedProfilesEnabled)return;long restore=LinkedRestoreProfile(close);if(restore>0&&Query("SELECT close_id FROM profile_links WHERE close_id=? AND auto_sync='1'",close.ToString()).Count==0)return;var entries=rows.Select(RestoreTarget).GroupBy(x=>x.Path,StringComparer.OrdinalIgnoreCase).Select(g=>g.OrderByDescending(x=>x.Selected).First()).ToList();
   if(restore==0){if(ListSets("profile_restore").Count>=5)throw new InvalidOperationException("恢复配置已达到 5 个，请先删除一个恢复配置或在配置管理中关联已有配置");restore=InsertSet("profile_restore",name,entries);Execute("INSERT OR REPLACE INTO profile_links(close_id,restore_id,auto_sync) VALUES(?,?,'1')",close.ToString(),restore.ToString());}
   else{Execute("DELETE FROM saved_entries WHERE set_id=?",restore.ToString());foreach(var r in entries)Execute("INSERT INTO saved_entries(set_id,name,path,args,admin,chosen,state) VALUES(?,?,?,?,?,?,?)",restore.ToString(),r.Name,r.Path,r.Args,r.Admin?"1":"0",r.Selected?"1":"0","");}
  }
  void ResyncLinksCore(){foreach(var link in Query("SELECT l.close_id,s.name FROM profile_links l JOIN saved_sets s ON s.id=l.close_id WHERE l.auto_sync='1'"))SyncProfileCore(long.Parse(link[0]),link[1],LoadSet(long.Parse(link[0])));}
 }
}
